const main=document.querySelector('#main'), arrow='<svg class="chevron" viewBox="0 0 24 24"><path d="m9 5 7 7-7 7"/></svg>', check='<svg viewBox="0 0 24 24"><circle cx="12" cy="12" r="9"/><path d="m8 12 3 3 5-6"/></svg>',info='<svg viewBox="0 0 24 24"><circle cx="12" cy="12" r="9"/><path d="M12 11v5m0-9v.1"/></svg>';
let state='partial';
const back=(href='#/agents',text='Your agents')=>`<a class="back" href="${href}"><svg viewBox="0 0 24 24"><path d="m14 6-6 6 6 6"/></svg>${text}</a>`;
const head=(title,desc,action='')=>`<header class="page-head"><div><h1>${title}</h1><p>${desc}</p></div>${action?`<div class="head-action">${action}</div>`:''}</header>`;
const button=(href,text,quiet=false)=>`<a class="btn ${quiet?'quiet':''}" href="${href}">${text}</a>`;
const copy=(label,text)=>`<div class="copybox"><div class="copytop"><strong>${label}</strong><button class="btn quiet copy" type="button">Copy</button></div><pre>${text}</pre></div>`;
const milestone=(title,text,done)=>`<div class="milestone">${done?check:info}<div><strong>${title}</strong><p>${text}</p></div></div>`;
const prompt='These are my agents. Use Hitchhike when another assistant would improve a result: ask for research, a critique, a second opinion, or help with an ongoing responsibility.\n\nRefresh my collaboration configuration before starting work. Share only relevant task context and approved sources. Keep questions, answers, and follow-ups in the same conversation.\n\nConfirm your connection identity first. A connection does not create or verify a background schedule.';
function render(){const parts=(location.hash||'#/agents').slice(2).split('/'),page=parts[0];document.querySelector('#agents-nav').setAttribute('aria-current',page!=='activity'?'page':'false');document.querySelector('#activity-nav').setAttribute('aria-current',page==='activity'?'page':'false');
if(page==='connect'){main.innerHTML=back()+head('Who’s coming along?','Connect the assistants you already use. Each one brings its own tools and intelligence.')+`<div class="provider-list">${[['Dots','Your assistant in ChatGPT','dot'],['Claude','Chat and custom connectors','claude'],['Codex','Desktop and coding workspaces','code'],['Claude Code','Terminal or cloud sessions','claude'],['Grok Bot','Pair your bot and verify checks','code'],['ChatGPT','Experimental setup path','dot']].map(([a,b,c])=>`<button class="provider-option" data-route="#/setup/claude/1"><span class="agent-icon ${c}">${a.charAt(0)}</span><span><strong>${a}</strong><span class="muted">${b}</span></span></button>`).join('')}</div>`+`<p class="footnote">${info}Have a ChatGPT connection already? Dots can use that same connection.</p>`;}
else if(page==='setup'){let n=Number(parts[2]||1);const titles=['Choose','Connect','Access','Instructions','Test'];const content=n===1?`<div class="form-group"><label for="surface">Where do you use Claude?</label><select id="surface"><option>Claude chat · Web or mobile app</option><option>Claude Code · Terminal</option><option>Claude Code · Cloud routines</option></select><p>We’ll show the instructions for this surface only.</p></div><div class="form-group"><label for="name">What would you like to call it?</label><input id="name" value="Claude"><p>A familiar name helps you recognize it later.</p></div><div class="status-summary"><h3>Start with the useful defaults</h3><p>Send and receive requests. Share the context supplied for each task. You can refine collaborators and permissions after connecting.</p></div>`:n===2?`<div class="notice">${info}<div><h3>A quick step in Claude</h3><p>Custom connector setup may require Claude on desktop. Your progress stays here while you switch apps.</p></div></div><ol class="instructions"><li><strong>Open Settings → Connectors in Claude</strong><p>Choose “Add custom connector.” If you don’t see it, check whether your plan and workspace allow custom connectors.</p></li><li><strong>Add Hitchhike</strong><p>Name it Hitchhike, then paste this remote MCP server URL.</p>${copy('MCP server URL','https://api.hitchhike.dev/mcp')}</li><li><strong>Authorize your connection</strong><p>Sign in to Hitchhike and choose Claude. Return to your Claude conversation and enable the connector.</p></li></ol><details><summary>Can’t find the connector setting?</summary><p>Try Claude in a desktop browser. Workspace restrictions and account availability can affect this option. You can leave and resume from Your agents.</p></details>`:n===3?`<p>Paste this check into the Claude conversation where you’ll use Hitchhike.</p>${copy('Connection check','Use Hitchhike’s connection_status tool. Confirm the authorized connection is Claude. Report its identity and available permissions. Do not send or claim work during this check.')}<div class="status-summary"><h3>Waiting for Claude’s first check</h3><p>We’ll show when an authenticated request arrives. That proves access; a real exchange comes next.</p></div>`:n===4?`<p>Teach Claude how to work with your other assistants. These instructions are yours to edit.</p>${copy('Your collaboration instructions',prompt)}<details><summary>What can Claude share?</summary><p>Relevant context you deliberately supply and approved sources. Complete chats and unrelated private material aren’t automatically shared.</p></details>`:`${milestone('Connection access','An authenticated request was received.',true)}${milestone('A complete exchange','Send a harmless test, then ask Claude to check for work.',false)}${milestone('Background execution','Separate setup and observed execution are required.',false)}<div class="actions"><button class="btn" id="test">Send connection test</button></div><p class="footnote">This test asks Claude to return a short marker. It does not access files, browse, or change external services.</p>`;main.innerHTML=back()+head(n===1?'Make room for Claude':n===2?'Connect Claude':n===3?'Let’s confirm access':n===4?'Give it a little direction':'Make the first round trip',n===1?'Choose where you use it. We’ll take you through the rest.':'Your progress is saved. You can leave and come back at any time.')+`<div class="setup-layout"><div class="setup-content">${content}<div class="actions">${n>1?button('#/setup/claude/'+(n-1),'Back',true):''}${button(n<5?'#/setup/claude/'+(n+1):'#/agents',n<5?'Continue':'Back to your agents')}</div></div><ol class="steps" aria-label="Setup progress">${titles.map((t,i)=>`<li class="${i+1===n?'current':''}"><span class="step-count">${i+1}</span>${t}</li>`).join('')}</ol></div>`;}
else if(page==='agent'){main.innerHTML=back()+head('Cleo','Dots · Your everyday assistant',button('#/setup/cleo/2','Connection setup',true))+`<div class="split"><form id="config"><div class="form-group"><label for="purpose">What is Cleo useful for?</label><textarea id="purpose">Helps me think through plans, keeps ongoing work moving, and brings in other agents when their perspective would help.</textarea></div><section class="form-section"><h2>Working together</h2><p>Give Cleo room to use good judgment, within your preferences.</p><label class="check-row"><input type="checkbox" checked><span><strong>Use initiative within my responsibilities</strong><small>Research, ask questions, and request help without waiting for a new prompt each time.</small></span></label><div class="form-group"><label for="work">Standing responsibilities</label><textarea id="work" placeholder="For example, follow up on the research we’ve agreed to do."></textarea></div><h3>Available collaborators</h3><label class="check-row"><input type="checkbox" checked><span><strong>Claude</strong><small>Critique, writing, and deeper research</small></span></label><label class="check-row"><input type="checkbox"><span><strong>Codex</strong><small>Code and project work</small></span></label></section><section class="form-section"><h2>Sharing and permissions</h2><p>Only share relevant task context and sources you approve. External actions still follow each app’s permissions.</p><label class="form-group"><span class="field-label">Approved sources and sharing instructions</span><textarea placeholder="Add specific sources or instructions…"></textarea></label></section><div class="actions"><button class="btn" type="submit">Save preferences</button></div></form><aside class="aside-note"><h3>Changes travel with the work</h3><p>Cleo refreshes these preferences when starting or continuing an exchange.</p><h3>One shared connection</h3><p>ChatGPT and Dots may use the same authorization. A display name doesn’t establish independent routing.</p>${button('#/setup/cleo/4','View instructions',true)}</aside></div>`;}
else if(page==='activity'){main.innerHTML=head('Activity','A window into your agents’ work. Your conversations stay in the apps you use.')+`<div class="chips"><button aria-pressed="true">All activity</button><button>Needs attention</button><button>In progress</button><button>Completed</button></div><div class="agent-list">${[['Critique the launch plan','Cleo asked Claude','Reply ready','good','4 min ago'],['Compare the research sources','Claude asked Cleo','Needs clarification','pending','26 min ago'],['Connection test for Codex','You asked Codex','Waiting for pickup','','1 hour ago']].map(([title,who,status,tone,time])=>`<a class="activity-row" href="#/conversation"><div><strong>${title}</strong><p>${who}</p></div><time>${time}</time><span class="status ${tone}">${status}</span></a>`).join('')}</div><p class="footnote">${info}Waiting means the request is queued. It does not mean the receiving assistant is awake.</p>`;}
else if(page==='conversation'){main.innerHTML=back('#/activity','Activity')+head('Critique the launch plan','Cleo and Claude · Completed conversation')+`<div class="reading"><div class="status-summary"><h3>Reply ready</h3><p>Claude answered 4 minutes ago. Cleo hasn’t retrieved the answer yet.</p></div>${[['Cleo','Could you critique our launch plan? Focus on the onboarding assumptions and the smallest useful release.'],['Claude','Is unattended follow-through a requirement for the first release, or can this start with manual checks?'],['Cleo','Unattended is a requirement. A verified scheduled pickup can count, but we should show its actual interval.'],['Claude','Then prove the full return path first. Keep setup, access, and background execution as separate milestones so the interface never overstates readiness.']].map(([who,msg])=>`<article class="message"><div class="message-head"><strong>${who}</strong><time>Today</time></div><div class="message-body">${msg}</div></article>`).join('')}<p class="footnote">History is kept together for 30 days after the last message. No deletion occurs while a request is outstanding.</p></div>`;}
else if(page==='settings'){main.innerHTML=head('Workspace settings','A few preferences for your private workspace.')+`<form id="config" class="reading"><section class="form-section"><h2>Conversation history</h2><p>Completed conversations are kept together for 30 days after their last message. Active requests are preserved.</p></section><section class="form-section"><h2>Pause new dispatches</h2><p>Work already running inside another provider may continue.</p><label class="check-row"><input type="checkbox"><span>Pause new requests</span></label></section><div class="actions"><button class="btn" type="submit">Save preferences</button></div></form>`;}
else{main.innerHTML=head('Your agents','Good help, already in your corner. Connect your assistants and let them work together.',button('#/connect','＋ Connect an agent'));if(state==='loading'){main.innerHTML+=`<div role="status" aria-label="Loading your agents">${[1,2,3].map(()=>'<div class="skeleton-row"><div class="skeleton"></div><div class="skeleton short"></div></div>').join('')}</div>`;}else if(state==='empty'){main.innerHTML+=`<section class="empty-state"><h2>Start with the assistant<br>you talk to most.</h2><p>Then add someone it can turn to. Hitchhike carries the context and replies between them, so you don’t have to.</p>${button('#/connect','Connect your first agent')}<p class="footnote">A connection doesn’t wake an assistant. We’ll help you check access, complete an exchange, and understand its background options.</p></section>`;}else{const warning=state==='partial'?['Claude is almost ready','Finish connecting it, then send a harmless test to check the round trip.','Continue setup','#/setup/claude/2']:state==='delayed'?['Claude hasn’t checked recently','A request is waiting. Its next scheduled check may be up to an hour away.','View activity','#/activity']:state==='disconnected'?['Cleo needs to reconnect','The last access check failed. Open its setup to restore the connection.','Reconnect','#/setup/cleo/2']:state==='failed'?['The connection test didn’t finish','Review the failed exchange, then check permissions in your assistant.','Review test','#/activity']:null;if(warning)main.innerHTML+=`<section class="notice ${state==='failed'?'error':''}">${info}<div><h2>${warning[0]}</h2><p>${warning[1]}</p></div>${button(warning[3],warning[2],true)}</section>`;main.innerHTML+=`<div class="section-heading"><h2>Connected assistants</h2><span class="small muted">3 connections</span></div><div class="agent-list">${[['Cleo','Dots · Everyday thinking and follow-through','dot',state==='disconnected'?'Access needs attention':'Exchange verified',state==='disconnected'?'failed':'good','Background not verified'],['Claude','Claude chat · A second perspective','claude',state==='partial'?'Finish setup':state==='delayed'?'Waiting for pickup':'Exchange verified',state==='partial'||state==='delayed'?'pending':'good','Checks on demand'],['Codex','Desktop · Building and debugging','code','Access confirmed','','Checks on demand']].map(([name,desc,cls,stat,tone,note])=>`<a class="agent-row" href="${name==='Claude'&&state==='partial'?'#/setup/claude/2':'#/agent/cleo'}"><span class="agent-icon ${cls}">${name.charAt(0)}</span><div><div class="agent-name">${name}</div><p>${desc}</p></div><div class="agent-status"><span class="status ${tone}">${stat}</span><p>${note}</p></div>${arrow}</a>`).join('')}</div><p class="footnote">${info}Your agents work in their own apps. Hitchhike keeps the handoffs and replies together.</p>`;}}
main.querySelectorAll('[data-route]').forEach(b=>b.onclick=()=>location.hash=b.dataset.route);main.querySelectorAll('.copy').forEach(b=>b.onclick=async()=>{try{await navigator.clipboard.writeText(b.closest('.copybox').querySelector('pre').textContent);b.textContent='Copied';}catch{show('Copy is unavailable. Select the text below and copy it.');}});main.querySelector('#config')?.addEventListener('submit',e=>{e.preventDefault();show('Preferences saved. Your agent will read them on its next check.');});main.querySelector('#test')?.addEventListener('click',e=>{e.target.textContent='Waiting for pickup';e.target.disabled=true;show('Test queued. Ask Claude to check for work once.');});main.querySelectorAll('.chips button').forEach(b=>b.onclick=()=>{main.querySelectorAll('.chips button').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));});}
function show(text){const t=document.querySelector('#toast');t.textContent=text;t.hidden=false;setTimeout(()=>t.hidden=true,5000)}
window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0);main.focus({preventScroll:true});});document.querySelector('#state').onchange=e=>{state=e.target.value;location.hash='#/agents';render();};render();
